+//! Reviewed NIFTY backfill. Evidence is separate from prices; only post-launch
+//! OHLC corroborated by the fixed official endpoint can reach Manual Import.
+use crate::bhavcopy::{build_nse_index_history_url, create_http_client, map_index_symbol,
+    NseIndexHistoryResponse, NseIndexHistoryTask, NSE_INDEX_HISTORY_PAGE_URL};
+use crate::database::binary_eod::{date_to_u32, BinaryEodFile, EodRecord, DEFAULT_SCALE};
+use crate::database::{get_active_database_file_path, get_price_storage_mode,
+    try_acquire_price_store_operation, PriceStorageMode, PriceStoreOperationKind};
+use crate::imports::{import_csv_internal_reviewed_nifty, notify_import_result, ImportOptionsInput, ImportResult, MANUAL_IMPORT_MUTATION_LOCK};
+use chrono::{Local, NaiveDate};
+use rusqlite::{Connection, OpenFlags};
+use serde::{Deserialize, Serialize};
+use sha2::{Digest, Sha256};
+use std::collections::{BTreeMap, HashMap};
+use std::fs::{self, OpenOptions};
+use std::io::{Read, Write};
+use std::path::{Path, PathBuf};
+use std::sync::{Mutex, OnceLock};
+use tauri::AppHandle;
+
+type Result<T> = std::result::Result<T, String>;
+const MAX_BYTES: u64 = 8_000_000;
+const LAUNCH: &str = "1996-04-22";
+const ALIASES: [&str; 4] = ["NIFTY", "NIFTY50", "CNXNIFTY", "SPCNXNIFTY"];
+
+#[derive(Clone, Debug, Deserialize)]
+#[serde(rename_all = "camelCase")]
+pub struct NiftyHistoryInput {
+    pub file_path: Option<String>,
+    pub from_date: String,
+    pub to_date: String,
+    /// False means local review only, never a trust assertion.
+    pub verify_official: bool,
+}
+
+#[derive(Clone, Debug, Serialize)]
+#[serde(rename_all = "camelCase")]
+pub struct HistoryRow {
+    pub date: String,
+    pub original_name: String,
+    pub open: Option<f64>,
+    pub high: Option<f64>,
+    pub low: Option<f64>,
+    pub close: Option<f64>,
+    pub volume: Option<u64>,
+    pub status: String,
+    pub reason: String,
+}
+
+impl HistoryRow {
+    fn prices(&self) -> Option<[f64; 4]> { Some([self.open?, self.high?, self.low?, self.close?]) }
+    fn record(&self) -> Result<EodRecord> {
+        let [o,h,l,c] = self.prices().ok_or("Close-only rows cannot become candles")?;
+        validate_ohlc([o,h,l,c])?;
+        Ok(EodRecord { date: date_to_u32(&self.date), flags: 0,
+            open: scaled(o), high: scaled(h), low: scaled(l), close: scaled(c),
+            prev_close: 0, volume: self.volume.unwrap_or(0), oi: 0 })
+    }
+}
+
+#[derive(Clone, Debug, Serialize)]
+#[serde(rename_all = "camelCase")]
+pub struct NiftyHistoryPreview {
+    pub token: String,
+    pub database_path: String,
+    pub source_sha256: String,
+    pub official_sha256: Option<String>,
+    pub source_url: Option<String>,
+    pub source_rows: usize,
+    pub ready: usize,
+    pub existing: usize,
+    pub conflicts: usize,
+    pub held: usize,
+    pub rejected: usize,
+    pub close_only: usize,
+    pub status: String,
+    pub certification_scope: String,
+    pub evidence_path: String,
+    pub rows: Vec<HistoryRow>,
+}
+
+#[derive(Clone)]
+struct Review {
+    database: PathBuf,
+    preview: NiftyHistoryPreview,
+    // The backend alone creates these after comparing official observations.
+    verified: Vec<HistoryRow>,
+}
+static REVIEWS: OnceLock<Mutex<HashMap<String, Review>>> = OnceLock::new();
+fn reviews() -> &'static Mutex<HashMap<String, Review>> { REVIEWS.get_or_init(|| Mutex::new(HashMap::new())) }
+fn hash(bytes: &[u8]) -> String { format!("{:x}", Sha256::digest(bytes)) }
+fn scaled(value: f64) -> i64 { (value * DEFAULT_SCALE as f64).round() as i64 }
+
+pub(crate) fn validate_ohlc(p: [f64; 4]) -> Result<()> {
+    if p.iter().any(|v| !v.is_finite() || *v <= 0.0 || *v > 1_000_000_000.0) {
+        return Err("Prices must be positive, finite and representable".into());
+    }
+    let [o,h,l,c] = p;
+    if h < o.max(c).max(l) || l > o.min(c).min(h) {
+        return Err("Invalid OHLC relationships".into());
+    }
+    Ok(())
+}
+
+pub(crate) fn historical_date(value: &str) -> Result<String> {
+    for format in ["%Y-%m-%d", "%d %b %Y", "%d-%b-%Y", "%d-%m-%Y", "%Y%m%d"] {
+        if let Ok(date) = NaiveDate::parse_from_str(value.trim(), format) {
+            return Ok(date.format("%Y-%m-%d").to_string());
+        }
+    }
+    Err(format!("Invalid historical date: {value}"))
+}
+
+fn optional_number(value: &str) -> Result<Option<f64>> {
+    let v = value.trim();
+    if ["", "-", "NA", "N/A", "NULL"].contains(&v.to_ascii_uppercase().as_str()) { return Ok(None); }
+    let number = v.replace(',', "").parse::<f64>().map_err(|_| format!("Invalid numeric value: {v}"))?;
+    if !number.is_finite() || number <= 0.0 || number > 1_000_000_000.0 { return Err(format!("Invalid price: {v}")); }
+    Ok(Some(number))
+}
+
+fn bounded_read(path: &Path) -> Result<Vec<u8>> {
+    let file = fs::File::open(path).map_err(|e| e.to_string())?;
+    let mut bytes = Vec::new();
+    file.take(MAX_BYTES + 1).read_to_end(&mut bytes).map_err(|e| e.to_string())?;
+    if bytes.len() as u64 > MAX_BYTES { return Err("Historical source exceeds 8 MB limit".into()); }
+    Ok(bytes)
+}
+
+fn parse_local(bytes: &[u8], today: &str) -> Result<Vec<HistoryRow>> {
+    let text = std::str::from_utf8(bytes).map_err(|_| "Historical CSV must be UTF-8")?.trim_start_matches('\u{feff}');
+    let mut reader = csv::ReaderBuilder::new().trim(csv::Trim::All).from_reader(text.as_bytes());
+    let headers = reader.headers().map_err(|e| e.to_string())?.clone();
+    let column = |names: &[&str]| headers.iter().position(|h| names.iter().any(|n| h.eq_ignore_ascii_case(n)));
+    let name = column(&["Index Name", "Index_Name", "Symbol"]).ok_or("CSV must identify Index Name or Symbol explicitly")?;
+    let date = column(&["Date", "Index Date", "Timestamp"]).ok_or("CSV missing Date")?;
+    let cols = ["Open", "High", "Low", "Close"].map(|n| column(&[n]).ok_or_else(|| format!("CSV missing {n}")));
+    let [o,h,l,c] = cols;
+    let cols = [o?,h?,l?,c?];
+    let vol = column(&["Volume", "Total Traded Quantity"]);
+    let mut rows = Vec::new();
+    for (i, record) in reader.records().enumerate() {
+        let r = record.map_err(|e| format!("CSV row {}: {e}", i+2))?;
+        let mut row = HistoryRow { date: r[date].into(), original_name: r[name].into(), open: None, high: None, low: None, close: None, volume: None, status: "HOLD".into(), reason: "Not verified against an official source".into() };
+        let parsed = (|| -> Result<()> {
+            row.date = historical_date(&r[date])?;
+            if row.date.as_str() < "1990-07-03" || row.date.as_str() > today { return Err("Date outside supported history or in the future".into()); }
+            if map_index_symbol(&row.original_name) != "NIFTY" { return Err("Only explicit NIFTY 50 aliases are supported".into()); }
+            row.open = optional_number(&r[cols[0]])?;
+            row.high = optional_number(&r[cols[1]])?;
+            row.low = optional_number(&r[cols[2]])?;
+            row.close = optional_number(&r[cols[3]])?;
+            if row.close.is_none() { return Err("Missing Close".into()); }
+            if let Some(p) = row.prices() { validate_ohlc(p)?; }
+            else if [row.open,row.high,row.low].iter().any(Option::is_some) { return Err("Partially missing OHLC".into()); }
+            if let Some(v) = vol {
+                let raw = r[v].replace(',', "");
+                if !["", "-", "NA", "N/A"].contains(&raw.as_str()) {
+                    let parsed = raw.parse::<u64>().map_err(|_| "Volume must be a nonnegative integer")?;
+                    if parsed > i64::MAX as u64 { return Err("Volume exceeds storage limit".into()); }
+                    // Source zero means unknown for an index; never invent volume.
+                    row.volume = (parsed > 0).then_some(parsed);
+                }
+            }
+            Ok(())
+        })();
+        if let Err(error) = parsed { row.status = "REJECTED".into(); row.reason = error; }
+        rows.push(row);
+    }
+    if rows.is_empty() { return Err("No historical observations in CSV".into()); }
+    mark_duplicates(&mut rows);
+    Ok(rows)
+}
+
+fn mark_duplicates(rows: &mut [HistoryRow]) {
+    let mut counts = HashMap::new();
+    for row in rows.iter() { *counts.entry(row.date.clone()).or_insert(0usize) += 1; }
+    for row in rows { if counts[&row.date] > 1 { row.status = "REJECTED".into(); row.reason = "Duplicate date; retain and resolve all observations before import".into(); } }
+}
+
+fn parse_official(bytes: &[u8], from: &str, to: &str, today: &str) -> Result<Vec<HistoryRow>> {
+    let response: NseIndexHistoryResponse = serde_json::from_slice(bytes).map_err(|e| format!("NSE response schema error: {e}"))?;
+    if response.error.unwrap_or(false) { return Err(response.show_message.unwrap_or("NSE API returned an error".into())); }
+    let records = response.data.ok_or("NSE response missing data; availability is unknown")?;
+    let mut rows = Vec::new();
+    for record in records {
+        let name = record.index_name.ok_or("NSE response missing index identity")?;
+        if map_index_symbol(&name) != "NIFTY" { return Err(format!("Unexpected NSE index identity: {name}")); }
+        let date = historical_date(&record.timestamp.ok_or("NSE response missing date")?)?;
+        if date.as_str() < from || date.as_str() > to || date.as_str() > today { return Err("NSE returned a date outside the requested range".into()); }
+        let mut row = HistoryRow { date, original_name: name, open: record.open, high: record.high, low: record.low, close: record.close, volume: None, status: "HOLD".into(), reason: String::new() };
+        // Confirmed API schema: pre-base history uses zero for unavailable OHL.
+        if row.date.as_str() < "1995-11-03" {
+            row.open = row.open.filter(|v| *v != 0.0);
+            row.high = row.high.filter(|v| *v != 0.0);
+            row.low = row.low.filter(|v| *v != 0.0);
+        }
+        if let Some(v) = record.traded_qty {
+            if !v.is_finite() || v < 0.0 || v.fract() != 0.0 || v >= i64::MAX as f64 { return Err("Invalid official volume".into()); }
+            row.volume = (v > 0.0).then_some(v as u64);
+        }
+        if row.close.is_none_or(|v| !v.is_finite() || v <= 0.0) { return Err("Invalid official Close".into()); }
+        if let Some(p) = row.prices() { validate_ohlc(p)?; }
+        else if [row.open,row.high,row.low].iter().any(Option::is_some) { return Err("Partially missing official OHLC".into()); }
+        rows.push(row);
+    }
+    mark_duplicates(&mut rows);
+    if rows.iter().any(|r| r.status == "REJECTED") { return Err("Official response contains duplicate dates".into()); }
+    if rows.is_empty() { return Err("NSE returned no observations; this does not prove a holiday or unavailable history".into()); }
+    Ok(rows)
